<script setup lang="ts">const amount=ref(500),purpose=ref('一般奉獻'),donation=ref<any>(null),result=ref('');const {error,run}=useApiError();async function create(){const r:any=await run(()=>api('/donations',{method:'POST',body:{amount:amount.value,purpose:purpose.value}}));donation.value=r} async function simulate(v:string){await run(()=>api(`/donations/${donation.value.id}/simulate`,{method:'POST',body:{result:v}}));result.value=v}</script>
<template><div class="pagehead"><div class="container"><div class="eyebrow">SUPPORT THE MINISTRY</div><h1>支持陪伴事工</h1></div></div><section class="section"><div class="container" style="max-width:650px"><div class="notice">這是安全的金流模擬頁面。未串接真實付款，不會收款或保存卡號。</div><form v-if="!donation" class="card form" style="margin-top:20px" @submit.prevent="create"><label class="field">支持金額（元）<input v-model.number="amount" type="number" min="1" required></label><label class="field">支持用途<select v-model="purpose"><option>一般奉獻</option><option>監所關懷</option><option>家庭支持</option></select></label><button class="button gold">建立模擬捐款</button></form><div v-else class="card"><h2>確認模擬結果</h2><p class="muted">金額：{{amount}} 元　用途：{{purpose}}</p><div class="actions"><button class="button" @click="simulate('success')">模擬成功</button><button class="button ghost" @click="simulate('failed')">模擬失敗</button><button class="button ghost" @click="simulate('cancelled')">取消</button></div><p v-if="result" class="notice">模擬交易結果：{{result}}。沒有產生真實付款。</p></div><p v-if="error" class="error">{{error}}</p></div></section></template>
